}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void updateEstimatedPre()
{
    next updateEstimatedPre();
   // this.setStatusRemainItemSet();
}

/// <summary>
/// designed from AVA
/// </summary>
protected void setStatusRemainItemSet()
{
    InventTransferLine          componentInventTransferLine;
    InventTransferLine          shipingInventTransferLine;
    if(inventTransferLine.AVAItemSet == NoYes::Yes && inventTransferLine.AVAItemSetExpanded == NoYes::Yes)
    {

        select sum(QtyRemainReceive), sum(QtyRemainShip) from componentInventTransferLine
            group by AVAItemSetParent
            where componentInventTransferLine.TransferId == inventTransferLine.TransferId
               && componentInventTransferLine.AVAItemSetParent == inventTransferLine.InventTransId;

        if (! componentInventTransferLine.QtyRemainShip && ! componentInventTransferLine.QtyRemainReceive)
        {
            inventTransferLine.RemainStatus = InventTransferRemainStatus::None;
        }
        else
        {
            if (! componentInventTransferLine.QtyRemainShip)
            {
                inventTransferLine.RemainStatus = InventTransferRemainStatus::Receiving;
            }
            else
            {
                inventTransferLine.RemainStatus = InventTransferRemainStatus::Shipping;
            }
        }

    }

}
